import subprocess, tempfile
from pathlib import Path
CASES=['4\nababcdefgabdefab ab\naaaaaaaaa a\naaaaaaaaa aaa \n112123323 a\n', '4\nabccba ac\naaccacc cac\ncacccbccbbbbc ca\nbbcbbccabaaac bca\n', '3\naacb aca\nabbbacaabcccbbbc ab\ncbcababccbc cbb\n', '2\nbbcbabacbbbcaaa cc\nccbababbbbbcbbaa acc\n', '4\ncacbbbccbbacaba aaa\ncabcbbbcbacbcbcc a\nbbbacbacbbbc aba\nbbabcacbbcabccc cbb\n', '4\nbbbb ac\nacbcaaabaa bb\nbbcaabaa aaa\naaaacbaa abb\n', '1\nbcacacbaabcccc acc\n', '4\ncbaabbca a\nabcabbc bbc\nccbaaa caa\naacabbbcbab bca\n', '3\ncabb bb\nbccaaca aa\ncabb bcb\n', '3\ncacccbabbacabcb c\ncacaababacbcbaac b\ncbcb bc\n', '3\naabaaaacccaac b\ncbbcacbbbb bca\ncaacaa cbb\n', '4\nccabaabacaa b\nbccbacbaccbacab bc\nbcabbb a\nbcbbbbabcaacaacc b\n', '4\ncacbcb a\ncabbc c\ncacbcbaaacccccac aaa\nbaaab acb\n', '3\nccbab a\ncacb bc\nbbcaccbaacaa ac\n', '2\naabbbbbbccccca baa\nbccbabaaabbcba cac\n', '3\ncabcabccbca ba\naacbabccacaaccac a\naabba aa\n', '4\nbbcacb a\naabcbaacbccbabbb b\nccbbcbbca a\naaaa cbc\n', '1\nbaccbb cb\n', '3\ncbbbcbac acc\nbacbbccbaccc bc\naaaaaca b\n', '4\nbbaaa cc\nbcbaabcccbccba a\nbbccbabaccb cba\nabcabcbaabaab bac\n']
SOURCE="# https://www.geeksforgeeks.org/naive-algorithm-for-pattern-searching/\n# Naive Pattern Searching algorithm\ndef search(pat, txt):\n    M = len(pat)\n    N = len(txt)\n\n    res = []\n    # A loop to slide pat[] one by one */\n    #for i in range(N - M + 1):\n    i = 0\n    while i < N - M + 1:\n        j = 0\n\n        # For current index i, check\n        # for pattern match */\n        while(j < M):\n            if (txt[i + j] != pat[j]):\n                i = i+j + 1\n                break\n            j += 1\n\n        if (j == M):\n            res.append(str(i))\n            i += M\n\n    return res\n\n\nn = int(input())\nfor _ in range(n):\n    txt, pat = input().split()\n    ans = search(pat, txt)\n    if ans:\n        print(' '.join(ans))\n    else:\n        print('no')\n"
with tempfile.NamedTemporaryFile('w',suffix='.py') as f:
 f.write(SOURCE); f.flush()
 root=Path(__file__).parent/'data'
 for i,c in enumerate(CASES):
  o=subprocess.run(['python3',f.name],input=c,text=True,capture_output=True,check=True).stdout
  (root/f'{i}.in').write_text(c); (root/f'{i}.out').write_text(o)
